/**
 * CSV Header Generator
 * ====================
 * Reads ALL_TABLE_CONFIGS (TableConfig[]) and generates per-table CSV header arrays.
 * Output: packages/schema/generated/csv.ts
 *
 * Migrated from TableDef (Phase 3): fieldTypes keys are snake_case column names directly —
 * no col.column lookup needed.
 */

import type { TableConfig } from '../utils';

export function generateCsv(tables: readonly TableConfig[]): string {
    const lines: string[] = [
        '// AUTO-GENERATED by @repo/schema — Do not edit manually.',
        '// Regenerate: pnpm --filter @repo/schema codegen',
        '',
    ];

    for (const table of tables) {
        const constName = table.name.toUpperCase().replace(/-/g, '_') + '_HEADERS';
        const headers = Object.keys(table.fieldTypes).map((f) => `"${f}"`);
        lines.push(`export const ${constName} = [${headers.join(', ')}] as const;`);
    }

    lines.push('');
    return lines.join('\n');
}
